UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 already-in-place (session-cluster-f-b, 2026-10-28; verification-layers-audited): the learning (each verification layer needs an audit of its own assumptions) is carried by layers that audit the other layers: probe review (probe_review_refused_share_7d, a guard metric, read 0.125 on 2026-10-28), the guard metrics of INTEGRITY-GUARDS-1 (remediation_latest_pass_pct_7d read 81.2), CORE-PROMPT-1 rule 7 (a change is verified by a probe its author did not write) and failure_modes_recurring (47). A per-layer self-audit document would add a layer, which ENSEMBLE-POLICY-1 keeps few.' WHERE id = 5508 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 rejected (session-cluster-f-b, 2026-10-28; analogy-only): the finding is about how human readers judge text that carries or lacks an AI label; no fleet quantity is named and no loop output changes. Whether published work states AI involvement is a publication-policy decision for the owner (identity and brand), not a loop rule; the trust ledger scores verified outcomes, not disclosure. Re-propose with a measured case in which a fleet output lost trust because of concealment.' WHERE id = 5509 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 rejected (session-cluster-f-b, 2026-10-28; keyword-proxy): turning an output that admits a limitation into an issue means matching admission phrases in model text, a hard gate on a keyword proxy; the same ruling was made on learnings 17, 47 and 48 on 2026-10-20. Unvalidated metrics are already found by measurement: output_quality_outcomes_unmeasured (4 on 2026-10-28) and proxy labelling in output_quality_measures (OUTPUT-QUALITY-LEDGER-1).' WHERE id = 5510 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 already-in-place (session-cluster-f-b, 2026-10-28; blocker-redteam): ANTIFRAGILE-1 requires an attempt, recorded in blocker_redteam, before the words blocked, cannot or owner only are written, so unknown is not taken for impossible; v_blocker_claims and the guard metric unverified_blocker_claims (25 on 2026-10-28) list every claim nobody tested, and blocker_surface_coverage_7d read 0.939.' WHERE id = 5511 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 already-in-place (session-cluster-f-b, 2026-10-28; provenance-fields): how an output was produced is a required, checkable field where outsiders read: every change to a paper carries change_actor and change_reason and is one immutable paper_change_ledger row (PAPER-LEDGER-1), a work claim records owner and intent (work_claims), and decision_log holds each autonomous decision with its evidence and rollback. A new mandatory field on issues and claims would duplicate these.' WHERE id = 5512 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 rejected (session-cluster-f-b, 2026-10-28; ensemble-review): ENSEMBLE-POLICY-1: LLM errors are correlated (a 9-judge, 7-family panel is worth about 2.2 votes), so a further model-written ignorance audit before every claim adds a layer from the same families; layers stay few, small and anchored on non-model checks (deterministic gate, reader votes, owner verdict). Re-propose with a measured case of an error an audit layer would have caught that the existing layers missed.' WHERE id = 5513 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 rejected (session-cluster-f-b, 2026-10-28; no-fleet-quantity): the caution is about the paper own n=3 binomial bound; it names no fleet threshold that was set from a handful of events. Fleet thresholds are owner caps and measured distributions, and a change is judged afterwards by fix_hold_rate_30d (0.5828 on 2026-10-28) over 30 days of closures. Re-propose with a metric threshold that was tightened after fewer than 5 breach events and then flapped.' WHERE id = 5581 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 rejected (session-cluster-f-b, 2026-10-28; analogy-only): the two framings are the paper own arithmetic over its own rows; the fleet metric whose denominator matters is handled where it is measured: OUTPUT-QUALITY-LEDGER-1 compares the same items a week apart, labels proxies, and counts only outcome measures toward the verdict, and each trigger states its formula in its definition of done. No fleet metric is named whose reframing changed a verdict.' WHERE id = 5586 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 rejected (session-cluster-f-b, 2026-10-28; analogy-only): the fleet loops are not numerical operators with a Lipschitz constant, and estimating one by perturbing a loop input means paid model calls while ai_spend caps are breached (BUDGET-SOFT-ROUTE-1 keeps work on the cheapest model). What the learning wants to know, whether a self-correcting loop settles on a result that holds, is measured directly: fix_hold_rate_30d (0.5828) and REMEDIATION-REOPEN-2 reopen a closure whose contract fails later.' WHERE id = 5570 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 rejected (session-cluster-f-b, 2026-10-28; analogy-only): dependence of an outcome on the initial guess is a property of the paper two-branch toy model. Concurrent fleet sessions are serialised on one file or issue by work claims (WORK-CLAIM-1), so two sessions do not start from different seeds on the same item, and no fleet quantity is named. Re-propose with two contested issues that ended differently because of the order sessions arrived in.' WHERE id = 5571 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'routed', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 routed (session-cluster-f-b, 2026-10-28; trigger-flap): routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, qnfo-fleet-control): METRIC-TRIGGER tickets close and reopen in a loop (167 reopens on 44 tickets in 7 days, measured 2026-10-26), which is the false-positive cost of acting on a deviation smaller than the sample behind it. A minimum sample before a trigger acts is within that issue lever space. This learning is closed against that issue, not by it.' WHERE id = 5572 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'routed', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 routed (session-cluster-f-b, 2026-10-28; trigger-flap): routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, qnfo-fleet-control): a minimum detectable deviation per registered metric is the same lever as the sample-size rule of learning 5572 and is owned by that issue, which carries the reopen counts as its closing probe. This learning is closed against that issue, not by it.' WHERE id = 5573 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 already-in-place (session-cluster-f-b, 2026-10-28; out-of-loop-observable): CORE-PROMPT-1 rule 7 requires that a change is verified by a probe the changing agent did not write, and PROBE-SYSTEMWIDE-1 runs runner-https probes from the GitHub runner, outside the Cloudflare account and outside the loop under test; probe review (probe_review_refused_share_7d 0.125) keeps the out-of-loop observable out of the loop own hands.' WHERE id = 5574 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 already-in-place (session-cluster-f-b, 2026-10-28; no-progress-ceiling): retry budgets already exist where loops can spin: NO-PROGRESS-CEILING-1 in qnfo-code-orchestrator stops retrying a code task when no new failure signature appears, RL_MAX_TRIES = 3 bounds the revision loop per paper version in qnfo-research-exec, and max_attempts bounds every remediation contract. Retries are correlated (tasks with 4 or more attempts merged 24 of 89, see learning 644), so a cap derived from a convergence rate adds nothing.' WHERE id = 5575 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 already-in-place (session-cluster-f-b, 2026-10-28; reverify-after-closure): a closure is re-measured after it: holding contracts re-verify about 55 minutes later, a closed issue whose contract later fails is reopened by REMEDIATION-REOPEN-2 (issue 100458 was reopened that way on 2026-10-28T14:40Z), and fix_hold_rate_30d (0.5828) grades how many closures held.' WHERE id = 5576 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 already-in-place (session-cluster-f-b, 2026-10-28; fix-hold-rate): closing on zero observed failures is already graded against what follows: fix_hold_rate_30d (0.5828 on 2026-10-28) and fix_target_hold_rate_30d (0.4901) count closures that held for 30 days, REMEDIATION-REOPEN-2 reopens a relapse, and an issue that was reopened needs two consecutive passes before it closes. That is the empirical version of the 3/N bound with the fleet own N.' WHERE id = 5589 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 already-in-place (session-cluster-f-b, 2026-10-28; closure-needs-measurement): listing a risk is not counted as having addressed it: an issue closes only with a live measurement in issue_triage.close_evidence (issue_close_evidence_required) or a passing contract probe, and the guard metric unverified_blocker_claims (25 on 2026-10-28) lists every named blocker nobody has tested.' WHERE id = 5526 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), status_note = 'PL-TRIAGE-1 rejected (session-cluster-f-b, 2026-10-28; analogy-only): no fleet loop treats uncertainty as generative and holds an issue open for inquiry; PRIORITY-QUEUE-1 already works critical before high before medium and raises an issue one level per 24 hours, and every issue has a contract probe. No fleet quantity is named. Re-propose with a safety-critical issue that sat open because it was classed as inquiry.' WHERE id = 5527 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', last_verdict = NULL, attempts = 0, max_attempts = 24, deferred_since = NULL, next_due_at = datetime('now'), module = 'cluster-f-b-real-probe', escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1, verify_transport = 'd1-query', verify_probe = 'SELECT ''promoted: ladder row active, newest cfmb-2 verdict promote, tool-call canary ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM model_ladder_models WHERE id = ''@cf/google/gemma-4-26b-a4b-it'') THEN ''no ladder row'' WHEN NOT EXISTS (SELECT 1 FROM model_ladder_models WHERE id = ''@cf/google/gemma-4-26b-a4b-it'' AND active = 1) THEN ''ladder row active=0'' WHEN COALESCE((SELECT verdict FROM cf_model_evals WHERE model_id = ''@cf/google/gemma-4-26b-a4b-it'' AND battery_version = ''cfmb-2'' ORDER BY run_ts DESC LIMIT 1), ''none'') <> ''promote'' THEN ''newest cfmb-2 verdict is not promote'' WHEN NOT EXISTS (SELECT 1 FROM routing_capability WHERE model = ''@cf/google/gemma-4-26b-a4b-it'' AND tool_call_ok = 1) THEN ''no routing_capability row with tool_call_ok=1'' ELSE ''promoted: ladder row active, newest cfmb-2 verdict promote, tool-call canary ok'' END AS observed' WHERE class = 'issue-1000594' AND issue_id = 1000594;
