UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', last_verdict = NULL, attempts = 0, max_attempts = 24, deferred_since = NULL, next_due_at = datetime('now'), module = 'cluster-f-b-real-probe', escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1, verify_transport = 'd1-query', verify_probe = 'SELECT ''closed'' AS expected, CASE WHEN (SELECT status FROM agent_issues WHERE id = 100596) IN (''closed'', ''resolved'') AND COALESCE((SELECT length(close_evidence) FROM issue_triage WHERE issue_id = 100596), 0) > 20 THEN ''closed'' ELSE ''issue 100596 is '' || COALESCE((SELECT status FROM agent_issues WHERE id = 100596), ''missing'') || '' without close evidence'' END AS observed' WHERE class = 'issue-1000502' AND issue_id = 1000502;
UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', last_verdict = NULL, attempts = 0, max_attempts = 24, deferred_since = NULL, next_due_at = datetime('now'), module = 'cluster-f-b-real-probe', escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1, verify_transport = 'd1-query@living-paper', verify_probe = 'SELECT ''0'' AS expected, CAST(COUNT(*) AS TEXT) AS observed FROM (SELECT body_md, rtrim(substr(body_md, 1, instr(body_md || char(10), char(10)) - 1), char(13)) AS fl, instr(body_md || char(10), char(10)) AS k FROM papers WHERE status = ''published'' AND version GLOB ''[2-9].*'' AND slug NOT IN (''a-unified-framework-for-superdeterminism-neurobiology-and-the-mechanics-of-human-meaning'', ''simulation-inconsistency-detection-via-neurobiological-and-cognitive-interfaces'')) WHERE ltrim(body_md) LIKE ''---%'' OR (fl LIKE ''# %'' AND (instr(substr(body_md, k + 1), char(10) || fl || char(10)) > 0 OR instr(substr(body_md, k + 1), char(10) || fl || char(13)) > 0))' WHERE class = 'issue-1000694' AND issue_id = 1000694;
UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', last_verdict = NULL, attempts = 0, max_attempts = 24, deferred_since = NULL, next_due_at = datetime('now'), module = 'cluster-f-b-real-probe', escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1, verify_transport = 'd1-query', verify_probe = 'SELECT ''indexed: sitemap lists the published set and an IndexNow engine answered within 7 days'' AS expected, CASE WHEN COALESCE((SELECT CAST(last_value AS INTEGER) FROM metric_registry WHERE metric = ''indexed_surface''), 0) < 700 THEN ''indexed_surface below 700'' WHEN COALESCE((SELECT CAST(last_value AS INTEGER) FROM metric_registry WHERE metric = ''seo_indexnow_engines_ok''), 0) < 1 THEN ''no IndexNow engine answered'' WHEN COALESCE((SELECT last_refreshed FROM metric_registry WHERE metric = ''seo_indexnow_engines_ok''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'') THEN ''seo_indexnow_engines_ok older than 7 days'' ELSE ''indexed: sitemap lists the published set and an IndexNow engine answered within 7 days'' END AS observed' WHERE class = 'issue-1000705' AND issue_id = 1000705;
UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', last_verdict = NULL, attempts = 0, max_attempts = 24, deferred_since = NULL, next_due_at = datetime('now'), module = 'cluster-f-b-real-probe', escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1, verify_transport = 'd1-query@living-paper', verify_probe = 'SELECT ''2'' AS expected, CAST(COUNT(*) AS TEXT) AS observed FROM papers WHERE slug IN (''a-unified-framework-for-superdeterminism-neurobiology-and-the-mechanics-of-human-meaning'', ''simulation-inconsistency-detection-via-neurobiological-and-cognitive-interfaces'') AND ltrim(body_md) LIKE ''# %'' AND instr(body_md, ''## Abstract'') > 0 AND body_md NOT LIKE ''%TOPIC COMPLEXITY ASSESSMENT%'' AND body_md NOT LIKE ''%Here is the continuation of the detailed%''' WHERE class = 'issue-1000701' AND issue_id = 1000701;
UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', last_verdict = NULL, attempts = 0, max_attempts = 24, deferred_since = NULL, next_due_at = datetime('now'), module = 'cluster-f-b-real-probe', escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1, verify_transport = 'd1-query', verify_probe = 'SELECT ''every reply row older than 60 minutes is tiered and drafted'' AS expected, CASE WHEN (SELECT COUNT(*) FROM email_reply_queue WHERE created_at >= ''2026-10-12 12:00:00'' AND human_score >= 2 AND tier IN (''1'', ''2'', ''3'')) < 3 THEN ''unmeasured: fewer than 3 tiered rows'' WHEN (SELECT COUNT(*) FROM email_reply_queue WHERE created_at >= ''2026-10-12 12:00:00'' AND human_score >= 2 AND decision <> ''closed'' AND created_at < datetime(''now'', ''-60 minutes'') AND NOT COALESCE(tier IN (''1'', ''2'', ''3'') AND (tier = ''1'' OR draft_proposed IS NOT NULL), 0)) > 0 THEN ''rows older than 60 minutes are untiered or undrafted'' ELSE ''every reply row older than 60 minutes is tiered and drafted'' END AS observed' WHERE class = 'issue-2373' AND issue_id = 2373;
UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', last_verdict = NULL, attempts = 0, max_attempts = 24, deferred_since = NULL, next_due_at = datetime('now'), module = 'cluster-f-b-real-probe', escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1, verify_transport = 'd1-query', verify_probe = 'SELECT ''owner decision recorded or credibility event or new confirmed subscriber'' AS expected, CASE WHEN COALESCE((SELECT CASE WHEN last_value GLOB ''[0-9]*'' THEN CAST(last_value AS INTEGER) ELSE 0 END FROM metric_registry WHERE metric = ''credibility_events_90d''), 0) >= 1 THEN ''owner decision recorded or credibility event or new confirmed subscriber'' WHEN EXISTS (SELECT 1 FROM subscribers WHERE confirmed_at > (SELECT MAX(ts) FROM owner_prompts WHERE id = ''op-mvihv5rr376f'')) THEN ''owner decision recorded or credibility event or new confirmed subscriber'' WHEN EXISTS (SELECT 1 FROM human_actions WHERE slug = ''attest-first-credibility-event'' AND status IN (''dismissed'', ''resolved'')) THEN ''owner decision recorded or credibility event or new confirmed subscriber'' ELSE ''owner step open: no event, no new subscriber, card undecided'' END AS observed' WHERE class = 'issue-100488' AND issue_id = 100488;
UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', last_verdict = NULL, attempts = 0, max_attempts = 24, deferred_since = NULL, next_due_at = datetime('now'), module = 'cluster-f-b-real-probe', escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1, verify_transport = 'd1-query', verify_probe = 'SELECT ''skills mirror recorded as unmaintained and its owner worker is retired'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE ''CLUSTER-F-B-1000152:%'') THEN ''no decision recorded'' WHEN EXISTS (SELECT 1 FROM service_registry WHERE service = ''qnfo-skill-sync'' AND COALESCE(state, '''') <> ''retired'') THEN ''qnfo-skill-sync is live in service_registry'' ELSE ''skills mirror recorded as unmaintained and its owner worker is retired'' END AS observed' WHERE class = 'issue-1000152' AND issue_id = 1000152;
UPDATE agent_issues SET description = replace(description, 'session-task: repo=qnfo-workers path=qnfo-research-exec/worker.js', 'code-task: repo=qnfo-workers path=qnfo-research-exec/worker.js') WHERE id = 1000477 AND instr(description, 'session-task: repo=qnfo-workers path=qnfo-research-exec/worker.js') > 0;
INSERT OR IGNORE INTO research_queue (id, source, source_id, idea, summary, score, decision, status, paper_slug, created_at, stage, attempt, revise_count, recover_count) SELECT 'rem-rev-cfb-1000701-a', 'remediation', 'revision:a-unified-framework-for-superdeterminism-neurobiology-and-the-mechanics-of-human-meaning@2.0.0#1', 'Post-publication revision of the published paper "A Unified Framework for Superdeterminism, Neurobiology, and the Mechanics of Human Meaning" (version 2.0.0). Write a complete, improved research paper under this title. The published version opens with the drafting model planning text and has no abstract, so it cannot be patched: write it from scratch with one H1 title, a ## Abstract, an introduction, numbered sections, a conclusion and a reference list, in the register of the lab other papers. Do not reuse outline wording as prose, do not mention outlines, planning or revision. Keep every claim the sources and derivations support and qualify or drop the rest.', '', 0.96, 'ACCEPT', 'queued', 'a-unified-framework-for-superdeterminism-neurobiology-and-the-mechanics-of-human-meaning', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), 'ground', 0, 0, 0 WHERE NOT EXISTS (SELECT 1 FROM research_queue WHERE source = 'remediation' AND paper_slug = 'a-unified-framework-for-superdeterminism-neurobiology-and-the-mechanics-of-human-meaning' AND status IN ('queued', 'researching', 'review'));
INSERT OR IGNORE INTO research_queue (id, source, source_id, idea, summary, score, decision, status, paper_slug, created_at, stage, attempt, revise_count, recover_count) SELECT 'rem-rev-cfb-1000701-b', 'remediation', 'revision:simulation-inconsistency-detection-via-neurobiological-and-cognitive-interfaces@2.1.0#1', 'Post-publication revision of the published paper "Simulation Inconsistency Detection via Neurobiological and Cognitive Interfaces" (version 2.1.0). Write a complete, improved research paper under this title. The published version opens with the drafting model planning text and has no abstract, so it cannot be patched: write it from scratch with one H1 title, a ## Abstract, an introduction, numbered sections, a conclusion and a reference list, in the register of the lab other papers. Do not reuse outline wording as prose, do not mention outlines, planning or revision. Keep every claim the sources and derivations support and qualify or drop the rest.', '', 0.96, 'ACCEPT', 'queued', 'simulation-inconsistency-detection-via-neurobiological-and-cognitive-interfaces', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), 'ground', 0, 0, 0 WHERE NOT EXISTS (SELECT 1 FROM research_queue WHERE source = 'remediation' AND paper_slug = 'simulation-inconsistency-detection-via-neurobiological-and-cognitive-interfaces' AND status IN ('queued', 'researching', 'review'));
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested) SELECT 'session-cluster-f-b', 'an issue with no doer closes only when its own contract measures its definition of done, so each probe was re-pointed to the records that definition names and each cause was fixed where it lives', 'CLUSTER-F-B-1000152: skills mirror prompts/skills/ is recorded as unmaintained (owner worker qnfo-skill-sync retired 2026-10-06, no reader in the fleet graph); and migrations/2026-10-28-cluster-f-b-drain.sql settles 18 PAPER-LEARN-1 learnings, re-points ten contracts, queues two paper regenerations (1000701) and relabels the code task of 1000477', 'read 2026-10-28: see the header of the migration file for the figure behind each issue', 'applied through the canonical path on merge', 'qnfo-audit paper_learnings (18 rows), remediation_contracts (10 rows), agent_issues 1000477 description, research_queue (2 rows); no worker, no secret', 'run the Rollback header of the migration (backups bak_20261028_cfb_*)', 'sixteen no-doer issues carry probes that measure their definition of done or a settled disposition', 'the five PAPER-LEARN-1 contracts read 0 at the next hourly tick and the autoclose trigger closes them; the other re-pointed contracts read their expected value on the next consumer run; 1000701 passes when the reviser publishes both regenerated papers', 'none', 'qnfo-audit paper_learnings, remediation_contracts, living-paper papers, metric_registry' WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'CLUSTER-F-B-1000152:%');
